contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The test takes callee and data as inputs. No Ether needs to be sent to C.forward.
    function run(address callee, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record balance of this test contract before calling C.forward
        uint balBefore = address(this).balance;

        bool didRevert;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // record balance after
        uint balAfter = address(this).balance;

        // General rule: calling c.forward does not increase this contract's balance.
        // i.e., balAfter <= balBefore OR the call reverted (we allow reverts)
        assert(balAfter <= balBefore || didRevert == true);
    }

    receive() external payable {}
}

